#!/bin/bash
# deploy_judiciary80: إدخال قانون تنظيم القضاء 80/2026 (87 كائنًا) + وسم إلغاء 23/1990 (82 كائنًا،
# النص يبقى محفوظًا كاملًا — لا حذف) + فهرسة كاملة + بطارية. يعمل في الخلفية (يصمد لانقطاع الطرفية).
if [ "$1" != "--worker" ]; then
  cp "$0" /opt/LegalMind/tools/_worker_judiciary80.sh 2>/dev/null || cp "$0" /tmp/_worker_judiciary80.sh
  W="/opt/LegalMind/tools/_worker_judiciary80.sh"; [ -f "$W" ] || W="/tmp/_worker_judiciary80.sh"
  rm -f /tmp/judiciary80.log
  nohup bash "$W" --worker > /tmp/judiciary80.log 2>&1 &
  echo "انطلق في الخلفية (PID $!) — إدخال + فهرسة كاملة + بطارية (قد يستغرق دقائق إلى ساعة حسب حجم القاعدة)."
  echo "التقدم: tail -f /tmp/judiciary80.log"
  exit 0
fi
set -o pipefail
cd /opt/LegalMind
set -a; . deploy/.env; set +a
mkdir -p /opt/LegalMind/tools /opt/legalmind-data

echo "[$(date +%T)] لقطة احتياطية لحالة 23/1990 قبل أي تعديل..."
psql -P pager=off "$DATABASE_URL" -c \
  "\copy (SELECT id, verification_status, usable_as_citation FROM knowledge_objects WHERE id LIKE 'legis-23-1990-%') TO '/opt/legalmind-data/legis23_1990_pre_repeal_$(date +%Y%m%d_%H%M%S).csv' WITH CSV HEADER" \
  || echo "تحذير: فشلت اللقطة الاحتياطية (غير حرجة، القاعدة نفسها هي المرجع)"

echo "[$(date +%T)] كتابة سكربت الإدخال إلى مسار دائم (لا /tmp — درس اليوم)..."
printf '%s' '' | base64 -d > /opt/LegalMind/tools/ingest_judiciary80_2026.py
python3 -c "import ast; ast.parse(open('/opt/LegalMind/tools/ingest_judiciary80_2026.py',encoding='utf-8').read())" \
  || { echo "فشل تحليل بايثون — توقف"; exit 1; }
echo "PYFILE_OK"

echo "[$(date +%T)] تنفيذ الإدخال (البيئة الثقيلة — تحتوي psycopg + normalize_text)..."
/opt/LegalMind/.venv/bin/python /opt/LegalMind/tools/ingest_judiciary80_2026.py 2>&1 | tee /tmp/judiciary80_ingest.log
grep -q "VERIFY_OK" /tmp/judiciary80_ingest.log || { echo "فشل الإدخال أو التحقق — توقف قبل الفهرسة"; exit 1; }

echo "[$(date +%T)] فهرسة كاملة..."
HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 \
  /opt/LegalMind/.venv/bin/python -m engine.legalmind_engine reindex 2>&1 | tee /tmp/judiciary80_reindex.log
grep -q '"consistent": true' /tmp/judiciary80_reindex.log || echo "تحذير: لم يظهر consistent:true صراحة — راجع اللوق يدويًا"

echo "[$(date +%T)] البطارية..."
/opt/LegalMind/admin/.venv/bin/python /opt/LegalMind/tools/battery_run.py 2>&1 | tee /tmp/judiciary80_battery.log
tail -4 /tmp/judiciary80_battery.log

echo "[$(date +%T)] عدّ نهائي..."
psql -P pager=off "$DATABASE_URL" -c \
  "SELECT (SELECT count(*) FROM knowledge_objects WHERE id LIKE 'legis-80-2026-%') AS new_law_80_2026,
          (SELECT count(*) FROM knowledge_objects WHERE id LIKE 'legis-23-1990-%' AND verification_status='superseded') AS repealed_23_1990,
          (SELECT count(*) FROM knowledge_objects) AS total_kb"

echo "[$(date +%T)] DONE_JUDICIARY80 — القانون 80/2026 مدخَل ومفهرس، و23/1990 موسوم بالإلغاء (نصه محفوظ)."
